function countBuiltStrings(low: number, high: number, zero: number, one: number): number {
  const MOD = 1_000_000_007;
  const maxBlocks = Math.floor(high / Math.min(zero, one));
  // pascal[n][k] = C(n, k) mod MOD
  const pascal: number[][] = [];
  for (let n = 0; n <= maxBlocks; n++) {
    pascal.push(new Array(n + 1).fill(1));
    for (let k = 1; k < n; k++) pascal[n][k] = (pascal[n - 1][k - 1] + pascal[n - 1][k]) % MOD;
  }
  let total = 0;
  for (let a = 0; a * zero <= high; a++) {
    for (let b = 0; a * zero + b * one <= high; b++) {
      if (a * zero + b * one >= low) total = (total + pascal[a + b][a]) % MOD;
    }
  }
  return total;
}

